from pathlib import Path
import json,csv,collections,math,hashlib,statistics,shutil
ROOT=Path(__file__).resolve().parents[1];S=ROOT/'data/analysis/replay_12bracos_20261021';D=S/'entrega';D.mkdir(exist_ok=True)
def read(n):return json.loads((S/n).read_bytes())
def write(n,s):(D/n).write_text(s+'\n',encoding='utf-8')
def f(x):return '—' if x is None else str(x) if isinstance(x,int) else f'{x:.4f}' if isinstance(x,float) else str(x)
def ci(x):return 'não estimado' if not x or not x.get('CI95') else '['+', '.join(f(v) for v in x['CI95'])+']'
def table(head,rows):return '\n'.join(['| '+' | '.join(head)+' |','| '+' | '.join(['---']*len(head))+' |']+['| '+' | '.join(f(v) for v in r)+' |' for r in rows])
def savecsv(name,rows):
 with (D/name).open('w',newline='',encoding='utf-8-sig') as h:
  w=csv.DictWriter(h,fieldnames=list(rows[0]));w.writeheader();w.writerows(rows)
def pct(x):return '—' if x is None else f'{100*x:.1f}%'
def ckey(x):return x['arm'],x['scenario'],x['path']
NAMES={'REAL_A':'REAL_A','BE_OFF_CB_SHADOW':'BE_OFF_CB','BE_OFF_CB_ACT20_GAP5_SHADOW':'ACT20_GAP5','BE_OFF_CB_ACT10_GAP13_SHADOW':'ACT10_GAP13','BE_OFF_CB_FAST_DROP_EMA_SHADOW':'FAST_DROP','HS_BULL_ELASTIC_SHADOW':'HS_BULL_ELASTIC','HS_BEAR_CLUSTER_EXIT_SHADOW':'HS_BEAR_CLUSTER','CB_EXIT_ALL_SHADOW':'CB_EXIT_ALL','BE_OFF_CB_MACD_BU_MINUS_SHADOW':'MACD_BU_MINUS','BE_OFF_CB_EMA_MACD_SHADOW':'EMA_MACD','EMA_MACD_HIST_1M_SHADOW':'HIST_1M','DMI15_TRAJECTORY_CONTEXT_SHADOW':'DMI15'}
