 arms=list(NAMES);sm={ckey(x):x for x in summaries};rb={ckey(x):x for x in rob};pidx={(x['arm'],x['scenario'],x['path'],x['dimension'],x['mare'],x['onda']):x for x in pairs};paths=['HIGH_FIRST','LOW_FIRST'];scenarios=['OPTIMISTIC','BASE','ADVERSE']
 # Supplemental descriptive distribution/instantaneous committed capital; no new simulation or threshold.
