    patterns.append({'arm':a,'control':xx[0]['control'],'dimension':dim,'mare':t,'onda':w,'positive_delta_cases_of6':sum(z['delta_total']>1e-10 for z in xx),'negative_delta_cases_of6':sum(z['delta_total']< -1e-10 for z in xx),'delta_min6':min(z['delta_total'] for z in xx),'delta_max6':max(z['delta_total'] for z in xx),'min_variant_N':min(z['arm_N'] for z in xx),'min_paired_N':min(z['paired_N'] for z in xx),'BASE_halves_positive_of4':sum(v>0 for z in bb for v in z['halves_entry_cohort_delta']),'BASE_positive_months_HF':sum(v>0 for v in bb[0]['monthly_entry_cohort_delta'].values()),'BASE_positive_months_LF':sum(v>0 for v in bb[1]['monthly_entry_cohort_delta'].values()),'BASE_excluding3days_HF':bb[0]['day_concentration_delta']['excluding_positive3'],'BASE_excluding3days_LF':bb[1]['day_concentration_delta']['excluding_positive3'],'BASE_CI72h_HF':ci(bb[0]['CI72h_delta']),'BASE_CI72h_LF':ci(bb[1]['CI72h_delta'])})
