  if control:
   pp=[pidx[a,s,p,'TOTAL',None,None] for s in scenarios for p in paths];bb=[pidx[a,'BASE',p,'TOTAL',None,None] for p in paths]
   lines+=['## Incremento sobre o controle','',table(['Custos','Caminho','Delta carteira','N pareados','Delta pareado','Delta/trade pareado','Residual trajetórias','Exposição delta'],[[z['scenario'],z['path'],z['delta_total'],z['paired_N'],z['paired_delta'],z['paired_delta_per_trade'],z['exclusive_and_censoring_residual'],z['delta_exposure_notional_hours']] for z in pp]),'', 'Pareamento pela fonte do sinal; entradas iguais são verificadas separadamente no JSON. Residual reúne admissões exclusivas e efeitos da trajetória, sem atribuição causal automática ao predicado. Não confundir seleção com saídas de uma população fixa.','',table(['Caminho base','Metades delta','Meses delta','Exclui top3 dias','LODO intervalo','IC95 dia','IC95 72h'],[[z['path'],'/'.join(f(v) for v in z['halves_entry_cohort_delta']),'; '.join(k+':'+f(v) for k,v in z['monthly_entry_cohort_delta'].items()),z['day_concentration_delta']['excluding_positive3'],'/'.join(f(v) for v in z['lodo_range_delta']),ci(z['CI_day_delta']),ci(z['CI72h_delta'])] for z in bb]),'']
   signs=sum(z['delta_total']>0 for z in pp);strict=all(z['CI72h_delta'].get('CI95') and z['CI72h_delta']['CI95'][0]>0 for z in bb);stable=all(min(z['halves_entry_cohort_delta'])>0 and z['day_concentration_delta']['excluding_positive3']>0 for z in bb)
